267	func listDeleteUserInboxIDs(ctx context.Context, tx *sql.Tx, userID int32, memoIDSet map[int32]struct{}) ([]int32, error) {
268		directIDs, err := listDeleteUserDirectInboxIDs(ctx, tx, userID)
269		if err != nil {
270			return nil, err
271		}
272		inboxIDs := append([]int32{}, directIDs...)
273		if len(memoIDSet) == 0 {
274			return inboxIDs, nil
275		}
276	
277		memoIDs, err := listDeleteUserMemoReferencedInboxIDs(ctx, tx, userID, memoIDSet)
278		if err != nil {
279			return nil, err
280		}
281		return append(inboxIDs, memoIDs...), nil
282	}
283	
284	func listDeleteUserDirectInboxIDs(ctx context.Context, tx *sql.Tx, userID int32) ([]int32, error) {
285		rows, err := tx.QueryContext(ctx, `
286			SELECT id
287			FROM inbox
288			WHERE sender_id = `+deleteUserPlaceholder(1)+`
289				OR receiver_id = `+deleteUserPlaceholder(2), userID, userID)
290		if err != nil {
291			return nil, err
292		}
293		defer rows.Close()
294	
295		inboxIDs := make([]int32, 0)
296		for rows.Next() {
297			var inboxID int32
298			if err := rows.Scan(&inboxID); err != nil {
299				return nil, err
300			}
301			inboxIDs = append(inboxIDs, inboxID)
302		}
303		if err := rows.Err(); err != nil {
304			return nil, err
305		}
306	
307		return inboxIDs, nil
308	}
309	
310	func listDeleteUserMemoReferencedInboxIDs(ctx context.Context, tx *sql.Tx, userID int32, memoIDSet map[int32]struct{}) ([]int32, error) {
311		rows, err := tx.QueryContext(ctx, `
312			SELECT id, message
313			FROM inbox
314			WHERE sender_id <> `+deleteUserPlaceholder(1)+`
315				AND receiver_id <> `+deleteUserPlaceholder(2), userID, userID)
316		if err != nil {
317			return nil, err
318		}
319		defer rows.Close()
320	
321		inboxIDs := make([]int32, 0)
322		for rows.Next() {
323			var (
324				inboxID    int32
325				messageRaw []byte
326			)
327			if err := rows.Scan(&inboxID, &messageRaw); err != nil {
328				return nil, err
329			}
330			if len(messageRaw) == 0 {
331				continue
332			}
333	
334			message := &storepb.InboxMessage{}
335			if err := protojsonUnmarshaler.Unmarshal(messageRaw, message); err != nil {
336				return nil, err
337			}
338			if inboxMessageTouchesMemoSet(message, memoIDSet) {
339				inboxIDs = append(inboxIDs, inboxID)
340			}
341		}
342		if err := rows.Err(); err != nil {
343			return nil, err
344		}
345	
346		return inboxIDs, nil
347	}
348	
349	func inboxMessageTouchesMemoSet(message *storepb.InboxMessage, memoIDSet map[int32]struct{}) bool {
350		if message == nil {
351			return false
352		}
353	
354		switch message.Type {
355		case storepb.InboxMessage_MEMO_COMMENT:
356			payload := message.GetMemoComment()
357			if payload == nil {
358				return false
359			}
360			return memoIDInSet(payload.MemoId, memoIDSet) || memoIDInSet(payload.RelatedMemoId, memoIDSet)
361		case storepb.InboxMessage_MEMO_MENTION:
362			payload := message.GetMemoMention()
363			if payload == nil {
364				return false
365			}
366			return memoIDInSet(payload.MemoId, memoIDSet) || memoIDInSet(payload.RelatedMemoId, memoIDSet)
367		default:
368			return false
369		}
370	}
371	
372	func memoIDInSet(id int32, memoIDSet map[int32]struct{}) bool {
373		if id == 0 {
374			return false
375		}
376		_, exists := memoIDSet[id]
377		return exists
378	}
