438	func deleteMemoRelationsTx(ctx context.Context, tx *sql.Tx, memoIDs []int32) error {
439		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
440			memoClause, args := deleteUserInClause(1, batch)
441			relatedClause, relatedArgs := deleteUserInClause(len(args)+1, batch)
442			query := `DELETE FROM memo_relation WHERE memo_id IN ` + memoClause + ` OR related_memo_id IN ` + relatedClause
443			args = append(args, relatedArgs...)
