133	func listDeleteUserMemoTreeIterative(ctx context.Context, tx *sql.Tx, userID int32) ([]deleteUserMemoRef, error) {
134		roots, err := queryDeleteUserMemoRefs(ctx, tx, `
135			SELECT id, uid
136			FROM memo
