143		seen := make(map[int32]struct{})
144		frontier := make([]int32, 0, len(roots))
145		for _, memo := range roots {
146			if _, exists := seen[memo.ID]; exists {
147				continue
148			}
149			seen[memo.ID] = struct{}{}
150			memos = append(memos, memo)
151			frontier = append(frontier, memo.ID)
152		}
153	
154		for len(frontier) > 0 {
155			currentFrontier := frontier
